import fs from 'fs';
import jwt from 'jsonwebtoken'; // npm install jsonwebtoken

const TOKEN_URL = "https://api.dynamox.solutions/v1/token";
const APPLICATION_KEY_PATH = "your_key.json";

function generateJwt(applicationKeyPath) {
    const key = JSON.parse(fs.readFileSync(applicationKeyPath, 'utf8'));
    return jwt.sign(
        {
            email: key.email,
            iat: Math.floor(Date.now() / 1000),
        },
        key.privateKey,
        {
            algorithm: 'RS256',
            keyid: key._id,
            header: { typ: 'JWT' },
        }
    );
}

function sleep(ms) {
    return new Promise(resolve => setTimeout(resolve, ms));
}

export async function getAccessToken() {
    try {
        const encodedJwt = generateJwt(APPLICATION_KEY_PATH);
        await sleep(2000);
        const response = await fetch(TOKEN_URL, {
            method: 'POST',
            headers: { Authorization: `Bearer ${encodedJwt}` },
        });
        const data = await response.json();
        console.log(data);
        return data.access_token;
    } catch (error) {
        console.error('Error:', error.message);
    }
}

getAccessToken();

tags.description:
The Token endpoint exchanges a signed JWT (created from your application key) for a short-lived access token used to authenticate API calls.

## Important: Token Generation Requirements

**Token generation must be implemented programmatically in your application code.** This process cannot be done manually or through the documentation interface because it requires:

- **JWT Library**: You need a JWT (JSON Web Token) library to create and sign tokens with the RS256 algorithm
- **Cryptographic Operations**: The token must be digitally signed using your private key
- **Dynamic Values**: Each token requires a current timestamp (`iat`) and proper payload structure

**Supported Languages**: We provide code examples for Python, Node.js, and cURL. You can use any programming language that supports JWT libraries and RS256 signing.

**Testing Flow**: After implementing token generation in your code, you can use the generated token in the documentation interface or external tools like Postman for API testing.

---

### Application key (JSON) — expected format

Save the application key exactly as provided by the platform. Example:

```json
{
  "_id": "$KEY_ID",
  "expiresAt": "$KEY_EXPIRES_AT",
  "applicationId": "$APPLICATION_ID",
  "email": "$APPLICATION_EMAIL",
  "publicKey": "$PUBLIC_KEY",
  "privateKey": "$PRIVATE_KEY"
}
```

Notes:

- privateKey must be a valid PEM RSA private key (convert escaped \n to newlines if necessary).
- expiresAt indicates when the application key expires — you cannot exchange an expired key.

Check [IANA - JSON Web Token (JWT)](https://www.iana.org/assignments/jwt/jwt.xhtml) for more details.

---

### JWT requirements

#### Header

```json
{
  "kid": "$KEY_ID",
  "alg": "RS256",
  "typ": "JWT"
}
```

- kid must match \_id from your application key.
- alg must be RS256.
- typ should be JWT.

#### Payload

```json
{
  "iat": 1700000000,
  "email": "app@example.com"
}
```

- iat — issued-at time, UTC timestamp in seconds.
- email — the email value from your application key.

---

### Step-by-step

The public API requires a short-lived access token issued by the Token endpoint. To obtain that access token:

- Use your **Application Key** (JSON) provided by the platform.
- Build a **JWT (RS256)** signed with the **privateKey** from the Application Key.
- Send the signed JWT to the Token endpoint (HTTP `POST`).
- Receive the **access token** to use in API calls.

---

## Code examples

### Python (PyJWT)

```python
import json
from datetime import datetime, timezone
from time import sleep

import jwt  # pip install pyjwt
import requests  # pip install requests

TOKEN_URL = "https://api.dynamox.solutions/v1/token"

APPLICATION_KEY_PATH = "your_key.json"

def generate_jwt(application_key_path: str) -> str:
    with open(application_key_path) as file:
        key = json.load(file)

    return jwt.encode(
      headers={
        "kid": key["_id"],
        "alg": "RS256",
        "typ": "JWT",
      },
      payload={
        "iat": datetime.now(timezone.utc).timestamp(),
        "email": key["email"],
      },
      key=key["privateKey"].encode("utf-8"),
    )

def main() -> None:
    encoded_jwt = generate_jwt(APPLICATION_KEY_PATH)
    sleep(2)
    response = requests.post(
        url=TOKEN_URL,
        headers={"Authorization": f"Bearer {encoded_jwt}"},
        timeout=10,
    )
    print(response.json())
    access_token = response.json().get("access_token")

if __name__ == "__main__":
    main()
```

### Node.js (jsonwebtoken)

```javascript
const fs = require("fs");
const jwt = require("jsonwebtoken"); // npm install jsonwebtoken

const TOKEN_URL = "https://api.dynamox.solutions/v1/token";
const APPLICATION_KEY_PATH = "your_key.json";

function generateJwt(applicationKeyPath) {
  const key = JSON.parse(fs.readFileSync(applicationKeyPath, "utf8"));
  return jwt.sign(
    {
      email: key.email,
      iat: Math.floor(Date.now() / 1000),
    },
    key.privateKey,
    {
      algorithm: "RS256",
      keyid: key._id,
      header: { typ: "JWT" },
    },
  );
}

function sleep(ms) {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

async function getAccessToken() {
  try {
    const encodedJwt = generateJwt(APPLICATION_KEY_PATH);
    await sleep(2000);
    const response = await fetch(TOKEN_URL, {
      method: "POST",
      headers: { Authorization: `Bearer ${encodedJwt}` },
    });
    const data = await response.json();
    console.log(data);
    return data.accessToken;
  } catch (error) {
    console.error("Error:", error.message);
  }
}

getAccessToken();
```

### cURL

Use the JWT generated from the Python or Node.js examples above:

```bash
curl -X POST "https://api.dynamox.solutions/v1/token" \
  -H "Authorization: Bearer <YOUR_JWT_HERE>"
```

---

## Common errors

- **401 Unauthorized (invalid signature):** check the private key and `kid`.
- **400 Bad Request (invalid `iat`):** ensure it is in seconds.
- **403 Forbidden (email mismatch):** check the email in the payload.
- **403 Forbidden (expired key):** verify `expiresAt`.

---

## Best practices

- Keep `privateKey` secret and never expose it.
- Use short-lived JWTs and tokens.
- Rotate Application Keys periodically.
- Always use TLS for requests.
